const KEY='ai-your-move-v1', $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch{}if(!state||state.version!==1)state={version:1,started:false,team:'',players:4,difficulty:'Stretch',remaining:2280,running:false,rounds:{},priorities:[],plans:{},words:{verb:'turn',quality:'responsible',outcome:'value'}};
let screen=state.started?'board':'intro', current=0, phase='vote', votes=[], choice=null, roundSeconds=240;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Browser storage unavailable. Export your report before leaving.')}}
function toast(t){$('#toast')?.remove();const d=document.createElement('div');d.id='toast';d.setAttribute('role','status');d.textContent=t;document.body.append(d);setTimeout(()=>d.remove(),4500)}
function completed(){return Object.keys(state.rounds).length}function button(text,fn,cls=''){const b=document.createElement('button');b.textContent=text;b.className=cls;b.onclick=fn;return b}function bind(id,fn){$(id).onclick=fn}function time(n){return `${Math.floor(n/60).toString().padStart(2,'0')}:${(n%60).toString().padStart(2,'0')}`}
function render(){ $('#progress').style.width=(completed()/7*100)+'%';if(screen==='intro')intro();else if(screen==='board')board();else if(screen==='round')round();else finale();tickDisplay() }
function intro(){ $('#app').innerHTML=`<section class="hero"><div><p class="eyebrow">THE LEADERSHIP LAB / 38-MINUTE TEAM CHALLENGE</p><h1>AI ambition.<br>Your next move.</h1><p class="lead">Seven dilemmas. Limited resources. A leadership team with decisions to make.</p><p class="muted">Debate the trade-offs, respond to the unexpected, and leave with three moves for the next 90 days.</p></div><div class="mark" aria-label="Seven dilemmas, one shared ambition"><div class="number">7</div><p>DILEMMAS</p><p>ONE SHARED AMBITION</p></div></section><form id="setup" class="setup"><label>Team name<input id="team" maxlength="60" required placeholder="e.g. The Next Move"></label><label>Players<select id="players">${[3,4,5,6].map(n=>`<option ${n===4?'selected':''}>${n}</option>`).join('')}</select><small>One shared device per team</small></label><label>Difficulty<select id="difficulty"><option>Standard</option><option selected>Stretch</option><option>Boardroom</option></select><small>Original dilemmas / constraints / pressure</small></label><button class="primary">Enter the board ↗</button></form><p class="muted">2 min briefing · 28 min dilemmas · 6 min priorities · 2 min closing pitch. No account required.</p>`;$('#setup').onsubmit=e=>{e.preventDefault();state.team=$('#team').value.trim();if(!state.team)return;state.players=+$('#players').value;state.difficulty=$('#difficulty').value;state.started=true;state.running=true;save();screen='board';render()}}
function board(){$('#app').innerHTML=`<div class="board-intro"><div><p class="eyebrow">${esc(state.team)} / ${esc(state.difficulty)} MODE</p><h1>The leadership board.</h1></div><div><p>Choose your next dilemma. Every decision unlocks part of your shared ambition.</p><p class="muted">Aim for 4 minutes per round. Explore the categories in any order.</p></div></div><div class="board">${ROUNDS.map((r,i)=>`<button class="tile ${state.rounds[i]?'done':''}" data-round="${i}"><span class="number">${String(i+1).padStart(2,'0')} ${state.rounds[i]?'✓':''}</span><div><h3>${r.name}</h3><small>${esc(r.theme)}</small></div><span>${state.rounds[i]?'Review decision':'Open dilemma ↗'}</span></button>`).join('')}<button class="tile finale" id="finale" ${completed()<7?'disabled':''}><span class="number">↗</span><h3>Your next<br>three moves</h3><small>${completed()===7?'Build your 90-day commitment':'Unlock all seven decisions first'}</small></button></div><div class="barline stats"><span><b>${completed()} / 7</b> decisions recorded</span><span class="muted">Completion reflects decisions recorded, not answer quality.</span><button id="export">Export current report</button></div>`;document.querySelectorAll('[data-round]').forEach(b=>b.onclick=()=>{current=+b.dataset.round;phase=state.rounds[current]?'record':'vote';votes=[];choice=null;roundSeconds=240;screen='round';render()});bind('#finale',()=>{screen='finale';render()});bind('#export',exportReport)}
function round(){const r=ROUNDS[current],old=state.rounds[current];$('#app').innerHTML=`<div class="roundtop"><button id="back">← Leadership board</button><span class="eyebrow">ROUND ${current+1} / 7 <span id="roundClock"></span></span></div><div class="round-layout"><section><p class="eyebrow">${r.name} / ${esc(r.theme)}</p><h2>${esc(r.title)}</h2><p class="scenario">${esc(r.scenario)}</p><div id="interaction"></div></section><aside class="aside"><p class="eyebrow">YOUR PLAYBOOK</p><h3>Choose. Challenge.<br>Commit.</h3><p>1. Vote privately<br>2. Reveal together<br>3. Debate the trade-offs<br>4. Agree your next move</p><p class="muted">Every option has a place. Make your assumptions explicit and invite a different view.</p><h3>Discussion prompt</h3><p>${esc(r.discuss)}</p>${current===3?'<div class="notice">All three review areas need attention before launch. Your vote identifies where to lead the discussion.</div>':''}<p class="eyebrow">${esc(state.difficulty)} MODE</p><p class="muted">${state.difficulty==='Standard'?'The original dilemma, with a concrete decision challenge.':state.difficulty==='Stretch'?'One new constraint after the reveal.':'Two pressure events, plus a required mitigation.'}</p></aside></div>`;bind('#back',()=>{screen='board';render()});const area=$('#interaction');
if(phase==='vote'){area.innerHTML=`<div class="phase"><p class="eyebrow">PRIVATE VOTE / PLAYER ${votes.length+1} OF ${state.players}</p><p>Pass the device to player ${votes.length+1}. Choose independently, then conceal your vote.</p><div class="options">${r.options.map((o,i)=>`<button class="option" data-choice="${i}"><div class="letter">${'ABC'[i]}</div><strong>${esc(o.title)}</strong><span>${esc(o.body)}</span></button>`).join('')}</div><button id="lock" class="primary" disabled>Conceal my vote</button></div>`;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{choice=+b.dataset.choice;document.querySelectorAll('[data-choice]').forEach(x=>x.classList.toggle('selected',x===b));$('#lock').disabled=false});bind('#lock',()=>{votes.push(choice);choice=null;phase=votes.length===state.players?'sealed':'pass';round()})}
else if(phase==='pass'||phase==='sealed'){area.innerHTML=`<div class="phase"><h3>Vote concealed.</h3><p>${votes.length===state.players?'All votes are in. Bring the team together before the reveal.':`Pass the device to player ${votes.length+1}.`}</p><button id="next" class="primary">${votes.length===state.players?'Reveal the team’s votes':'I’m the next player'}</button></div>`;bind('#next',()=>{phase=votes.length===state.players?'reveal':'vote';round()})}
else if(phase==='reveal'){area.innerHTML=`<div class="phase"><p class="eyebrow">THE REVEAL</p><div class="votes">${r.options.map((o,i)=>`<div class="vote"><b>${votes.filter(v=>v===i).length}</b>${'ABC'[i]} · ${esc(o.title)}</div>`).join('')}</div><h3>${new Set(votes).size===1?'You agree. What assumption could you all be missing?':'Different instincts. Start with the minority view.'}</h3><p>${esc(r.discuss)}</p>${state.difficulty!=='Standard'?`<div class="twist"><p class="eyebrow">PLOT TWIST</p><p>${esc(r.twists[0])}</p>${state.difficulty==='Boardroom'?`<b>Boardroom escalation</b><p>${esc(r.twists[1])}</p>`:''}<p>Does this change your decision? Explain why.</p></div>`:''}<p><b>Decision challenge:</b> ${esc(r.challenge)}</p><button id="commit" class="primary">Agree our decision ↗</button></div>`;bind('#commit',()=>{phase='record';round()})}
else {area.innerHTML=`<form id="record" class="phase"><p class="eyebrow">${old?'YOUR RECORDED DECISION':'TEAM COMMITMENT'}</p><div class="fields"><label class="wide">Agreed direction<select id="decision">${r.options.map((o,i)=>`<option value="${i}" ${old?.decision===i?'selected':''}>${'ABC'[i]} · ${esc(o.title)}</option>`).join('')}</select></label><label class="wide">Our action and business reason<textarea id="reason" required maxlength="1500" placeholder="We will… because…">${esc(old?.reason)}</textarea></label><label>Accountable owner<input id="owner" required maxlength="100" value="${esc(old?.owner)}" placeholder="Name or role"></label><label>Evidence and review point<input id="evidence" required maxlength="300" value="${esc(old?.evidence)}" placeholder="Measure, threshold and review date"></label>${state.difficulty==='Boardroom'?`<label class="wide">Risk mitigation<textarea id="mitigation" required maxlength="800" placeholder="The main risk is… Our safeguard is…">${esc(old?.mitigation)}</textarea></label>`:''}${wordFields(current)}</div><div class="actions"><button class="primary">${old?'Save updated decision':'Lock decision & unlock words'} ↗</button></div></form>`;$('#record').onsubmit=e=>{e.preventDefault();for(const id of ['reason','owner','evidence',...(state.difficulty==='Boardroom'?['mitigation']:[])]){if(!$('#'+id).value.trim()){$('#'+id).focus();return}}state.rounds[current]={decision:+$('#decision').value,reason:$('#reason').value.trim(),owner:$('#owner').value.trim(),evidence:$('#evidence').value.trim(),mitigation:$('#mitigation')?.value.trim()||'',votes:old?.votes||votes.slice()};document.querySelectorAll('[data-word]').forEach(s=>state.words[s.dataset.word]=s.value);save();screen='board';render();toast(`Decision locked. ${unlocked(current)}`)}}tickDisplay()}
function wordFields(i){const defs={0:['outcome',['value','meaningful impact','sustainable growth']],2:['verb',['turn','transform','translate']],3:['quality',['responsible','trusted','ethical']]};if(!defs[i])return `<p class="wide notice">Word unlock: <b>${esc(unlocked(i))}</b></p>`;const [key,opts]=defs[i];return `<label class="wide">Choose your ${key}<select data-word="${key}">${opts.map(x=>`<option ${state.words[key]===x?'selected':''}>${x}</option>`).join('')}</select><small>Explain how your action makes this word credible.</small></label>`}
function unlocked(i){return [state.words.outcome,'Together we',state.words.verb,state.words.quality,'AI','into','Your shared ambition'][i]}function sentence(){return `Together we ${state.words.verb} ${state.words.quality} AI into ${state.words.outcome}.`}
function finale(){if(completed()<7){screen='board';render();return}$('#app').innerHTML=`<p class="eyebrow">FINAL CHALLENGE / 8 MINUTES</p><h1>You have three moves.</h1><p class="scenario">Seven decisions support one shared ambition. Now choose the three actions that matter most in the next 90 days.</p><div class="sentence">${esc(sentence())}</div><p>Select exactly three priorities. Make each one specific enough to act on tomorrow.</p><div id="priorities">${ROUNDS.map((r,i)=>`<section class="priority"><label><input type="checkbox" data-priority="${i}" ${state.priorities.includes(i)?'checked':''}>${r.name} · ${esc(r.options[state.rounds[i].decision].title)}</label><p>${esc(state.rounds[i].reason)}</p><div id="plan${i}"></div></section>`).join('')}</div><div class="actions"><button id="finish" class="primary">Complete the leadership challenge ↗</button><button id="export">Export workshop report</button><button id="board">Back to board</button></div><div id="closing" role="status"></div>`;document.querySelectorAll('[data-priority]').forEach(b=>{b.onchange=()=>{const i=+b.dataset.priority;if(b.checked&&state.priorities.length===3){b.checked=false;toast('Choose three priorities. Deselect one to replace it.');return}state.priorities=b.checked?[...state.priorities,i]:state.priorities.filter(x=>x!==i);state.finished=false;$('#closing').innerHTML='';save();plans()}});bind('#board',()=>{screen='board';render()});bind('#export',exportReport);bind('#finish',finish);plans();if(state.finished)closing()}
function plans(){ROUNDS.forEach((r,i)=>{const a=$('#plan'+i);a.innerHTML='';if(!state.priorities.includes(i))return;const p=state.plans[i]||{};a.innerHTML=`<div class="fields"><label>Owner<input data-plan="owner" value="${esc(p.owner||state.rounds[i].owner)}" maxlength="100"></label><label>First step in the next 7 days<input data-plan="step" value="${esc(p.step)}" maxlength="400"></label><label>Evidence of progress by day 90<input data-plan="evidence" value="${esc(p.evidence)}" maxlength="400"></label><label>Review date<input type="date" data-plan="review" value="${esc(p.review)}"></label></div>`;a.querySelectorAll('[data-plan]').forEach(el=>el.oninput=()=>{state.plans[i]={...state.plans[i],owner:a.querySelector('[data-plan=owner]').value,[el.dataset.plan]:el.value};state.finished=false;$('#closing').innerHTML='';save()})})}
function finish(){if(state.priorities.length!==3){toast('Select exactly three priorities.');return}for(const i of state.priorities){for(const key of ['owner','step','evidence','review']){const el=$(`#plan${i} [data-plan=${key}]`);if(!el.value.trim()){el.focus();toast('Complete every commitment field for your three moves.');return}}state.plans[i]=Object.fromEntries([...$('#plan'+i).querySelectorAll('[data-plan]')].map(el=>[el.dataset.plan,el.value.trim()]))}state.finished=true;state.running=false;save();closing()}
function closing(){$('#closing').innerHTML=`<div class="twist"><p class="eyebrow">CHALLENGE COMPLETE / 7 DECISIONS / 3 COMMITMENTS</p><h2>Your next move starts now.</h2><p>Give a two-minute closing pitch: “Our three moves are… because…” Name the trade-off you accepted, the owner of each move, and the evidence you will review.</p><button id="finalExport" class="primary">Download our action report</button></div>`;bind('#finalExport',exportReport);$('#closing').scrollIntoView({behavior:'smooth'})}
function exportReport(){const lines=[`AI: YOUR MOVE — ${state.team||'Workshop draft'}`,`Difficulty: ${state.difficulty}`,`Status: ${state.finished?'Complete':'In progress'}`,`Decisions: ${completed()}/7`,'',completed()===7?sentence():'Shared ambition unlocks after all seven decisions.','',...ROUNDS.flatMap((r,i)=>{const d=state.rounds[i];return [`${i+1}. ${r.name}`,d?`Direction: ${r.options[d.decision].title}\nAction and reason: ${d.reason}\nOwner: ${d.owner}\nEvidence / review: ${d.evidence}\n${d.mitigation?'Mitigation: '+d.mitigation+'\n':''}Votes (A/B/C): ${[0,1,2].map(n=>(d.votes||[]).filter(v=>v===n).length).join('/')}`:'Not yet recorded','']}),'NEXT 90 DAYS',...state.priorities.flatMap((i,n)=>{const p=state.plans[i]||{};return [`${n+1}. ${ROUNDS[i].name}`,`Owner: ${p.owner||state.rounds[i].owner}`,`First 7 days: ${p.step||'Pending'}`,`Evidence by day 90: ${p.evidence||'Pending'}`,`Review date: ${p.review||'Pending'}`,'']}),'Based on the supplied AI: Your Move workshop deck. Additional twists are fictional workshop scenarios. No answer is a universal recommendation.'];const blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='AI-Your-Move-action-report.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function tickDisplay(){$('#clock').textContent=`${time(state.remaining)} · ${state.running?'Pause':'Resume'}`;if($('#roundClock'))$('#roundClock').textContent=` / ${time(roundSeconds)} suggested`}
$('#clock').onclick=()=>{if(!state.started)return;state.running=!state.running;save();tickDisplay()};$('#home').onclick=e=>{e.preventDefault();screen=state.started?'board':'intro';render()};$('#guide').onclick=()=>$('#help').showModal();$('#closeHelp').onclick=()=>$('#help').close();$('#reset').onclick=()=>{if(confirm('Clear this device’s saved workshop? Export your report first if needed.')){try{localStorage.removeItem(KEY)}catch{}location.reload()}};
setInterval(()=>{if(!state.running||!state.started)return;if(state.remaining>0)state.remaining--;if(screen==='round'&&roundSeconds>0)roundSeconds--;if(state.remaining===0){state.running=false;toast('38 minutes reached. Finish your discussion at your own pace.')}save();tickDisplay()},1000);render();
